/**
 * The mandatory message for a view with nothing to show (`design/components/empty-state.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/empty-state.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { Icon, claimSlot, resolveSlot, scope, type Defaults, type IconRole } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/empty-state.module.css'
import Inline from '../layout/Inline'

export interface EmptyStateProps {
  /**
   * One Button, `soft`/`accent` by convention, so the page's own primary stays primary.
   */
  action?: JSX.Element
  /**
   * What to do about it.
   */
  description?: string
  icon?: IconRole
  /**
   * A `ghost` Button, such as "Clear filters".
   */
  secondaryAction?: JSX.Element
  /**
   * Describes the situation, such as "No tickets yet" rather than "Empty".
   */
  title: string
}

/** The mandatory message for a view with nothing to show. */
export default function EmptyState(given: EmptyStateProps): JSX.Element {
  const props = mergeProps({ icon: 'inbox' } as Defaults<EmptyStateProps, 'icon'>, claimSlot(given))
  return scope(() => {
    const actionSlot = resolveSlot(() => props.action)
    const secondaryActionSlot = resolveSlot(() => props.secondaryAction)
    return (
      <div class={styles.empty} data-member="empty-state">
        {/* well */}
        <span class={styles.well}>
          <Icon name={props.icon} size="lg" />
        </span>
        {/* title */}
        <h2 class={styles.title}>{props.title}</h2>
        {props.description !== undefined ? (
          <p class={styles.description}>{props.description}</p>
        ) : null}
        {actionSlot.filled() || secondaryActionSlot.filled() ? (
          <div class={styles.actions}>
            <Inline gap={3} wrap={true} justify="center">
              {actionSlot()}
              {secondaryActionSlot()}
            </Inline>
          </div>
        ) : null}
      </div>
    )
  })
}
